"use client";
import { useEffect, useRef, useState } from "react";
import { supabase } from "@/lib/supabase";
import { ICONS } from "@/lib/icons";

const LOGO = "data:image/png;base64,";
const FABRIC = "data:image/jpeg;base64,";

const CSS = `html{scroll-behavior:smooth}
.ks{--bg:#fdf9f4;--fg:#241c15;--muted:#6b6258;--line:#e4dccf;--gold:#a37f3a;background:var(--bg);color:var(--fg);min-height:100dvh;font-family:"DM Sans",system-ui,sans-serif;color-scheme:only light}
.ks *{box-sizing:border-box}
.ks a{color:inherit;text-decoration:none}
.ks-wrap{max-width:1200px;margin:0 auto;padding-left:max(20px,env(safe-area-inset-left,0px));padding-right:max(20px,env(safe-area-inset-right,0px))}
.ks-head{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-block:20px}
.ks-brand{display:flex;align-items:center;gap:12px;font-family:"Cormorant Garamond",Georgia,serif;font-size:1.2rem;letter-spacing:.36em;text-transform:uppercase;white-space:nowrap}
.ks-brand img{height:44px;width:auto}
.ks-brand span{color:var(--gold)}
.ks-nav{display:flex;gap:clamp(14px,3vw,38px);font-size:.72rem;letter-spacing:.22em;text-transform:uppercase}
.ks-nav a{color:var(--muted);padding:10px 2px}
.ks-nav a:first-child{color:var(--fg);font-weight:500}
.ks-nav a:hover{color:var(--gold)}
.ks-hero{display:grid;grid-template-columns:1fr 1fr;gap:clamp(32px,6vw,90px);align-items:center;padding-block:clamp(20px,5vw,64px) clamp(40px,7vw,90px)}
.ks-hero h1{font-family:"Cormorant Garamond",Georgia,serif;font-weight:500;font-size:clamp(2.5rem,6vw,4.4rem);line-height:1.02;text-transform:uppercase;margin:0}
.ks-hero h1 em{display:block;text-transform:none;font-style:italic;color:var(--gold);margin-top:.15em}
.ks-rule{border:0;border-top:1px solid var(--fg);margin:clamp(20px,3vw,32px) 0}
.ks-hero p{color:var(--muted);line-height:1.75;font-size:1.02rem;margin:0 0 22px;max-width:46ch}
.ks-form{display:flex;gap:10px;flex-wrap:wrap;margin:0 0 6px}
.ks-form input{flex:1 1 220px;min-width:0;padding:14px 16px;font:inherit;font-size:1rem;background:#fff;color:var(--fg);border:1px solid var(--line);border-radius:10px}
.ks-form input:focus{outline:2px solid var(--gold);outline-offset:1px}
.ks-form button{padding:14px 22px;font:inherit;font-size:.78rem;letter-spacing:.14em;text-transform:uppercase;font-weight:500;background:var(--fg);color:#fff;border:0;border-radius:10px;cursor:pointer}
.ks-form button:disabled{opacity:.6}
.ks-ok{color:#2f6b3e;font-weight:500;margin:6px 0 0}
.ks-err{color:#a33;margin:6px 0 0;font-size:.92rem}
.ks-phil{border-top:1px solid var(--gold);padding-block:clamp(44px,7vw,84px);text-align:center}.ks-phil .ks-label{margin-bottom:22px}.ks-phil blockquote{margin:0 auto;max-width:22em;font-family:"Cormorant Garamond",Georgia,serif;font-style:italic;font-weight:600;font-size:clamp(1.6rem,4vw,2.6rem);line-height:1.25;text-wrap:balance}.ks-phil p{margin:26px auto 0;max-width:40em;color:var(--fg);font-size:1.05rem}.ks-phil small{display:block;margin-top:18px;font-size:.78rem;letter-spacing:.14em;color:var(--muted)}
.ks-img{position:relative}
.ks-name span{display:inline-block;opacity:0;transform:translateY(-1.4em)}
.ks-name.ks-in span{animation:ksDrop .7s calc(var(--i)*110ms) both cubic-bezier(.2,.8,.2,1)}
@keyframes ksDrop{from{opacity:0;transform:translateY(-1.4em)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.ks-name span{opacity:1;transform:none}}
.ks-img{border-radius:18px;overflow:hidden;box-shadow:0 30px 60px -25px rgba(60,40,15,.35);animation:ksUp 1s .15s both,ksFloat 7s 1.2s ease-in-out infinite}
.ks-img img{display:block;width:100%;aspect-ratio:4/5;object-fit:cover;animation:ksZoom 16s ease-in-out infinite alternate}
.ks-hero>div:first-child h1{animation:ksUp .9s both}
.ks-hero>div:first-child>p,.ks-hero>div:first-child>hr{animation:ksUp .9s .2s both}
.ks-form,.ks-ok{animation:ksUp .9s .4s both}
.ks-form button{transition:transform .2s,box-shadow .2s;animation:ksPulse 3s 1.5s ease-in-out infinite}
.ks-form button:hover{transform:translateY(-2px);box-shadow:0 10px 20px -8px rgba(36,28,21,.5)}
@keyframes ksUp{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}
@keyframes ksFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-12px)}}
@keyframes ksZoom{from{transform:scale(1)}to{transform:scale(1.12)}}
@keyframes ksPulse{0%,100%{box-shadow:0 0 0 0 rgba(163,127,58,.0)}50%{box-shadow:0 0 0 7px rgba(163,127,58,.22)}}
@media(prefers-reduced-motion:reduce){.ks *{animation:none!important;transition:none!important}}
.ks-sec{border-top:1px solid var(--line);padding-block:clamp(40px,6vw,72px);scroll-margin-top:10px}
.ks-grid{display:grid;grid-template-columns:200px 1fr;gap:24px}
.ks-label{font-size:.72rem;letter-spacing:.24em;text-transform:uppercase;color:var(--muted)}
.ks-sec h2{font-family:"Cormorant Garamond",Georgia,serif;font-weight:500;font-size:clamp(1.7rem,3.6vw,2.4rem);margin:0 0 14px}
.ks-sec p{margin:0;line-height:1.8;color:var(--muted);max-width:62ch}
.ks-tel{font-family:"Cormorant Garamond",Georgia,serif;font-size:1.7rem;display:inline-block;margin-bottom:18px}
.ks-links{display:flex;gap:12px}
.ks-links a{width:52px;height:52px;border:1px solid var(--line);border-radius:50%;display:inline-flex;align-items:center;justify-content:center;background:#fff;transition:.2s}
.ks-links a:hover{border-color:var(--gold);color:var(--gold)}
.ks-links svg{width:22px;height:22px;fill:currentColor}
.ks-foot{border-top:1px solid var(--line);padding-block:22px;font-size:.82rem;color:var(--muted);display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
@media(max-width:820px){.ks-hero{grid-template-columns:1fr}.ks-img img{aspect-ratio:4/3}.ks-grid{grid-template-columns:1fr;gap:10px}.ks-head{flex-wrap:wrap}.ks-brand{font-size:1rem;letter-spacing:.28em}.ks-brand img{height:38px}}`;

const LINKS = [
  { k: "whatsapp", l: "WhatsApp", h: "https://wa.me/252770714732" },
  { k: "instagram", l: "Instagram", h: "https://www.instagram.com/miro.store.so" },
  { k: "tiktok", l: "TikTok", h: "https://www.tiktok.com/@miro.store.somalia" },
];

export default function OpeningSoon() {
  const [email, setEmail] = useState("");
  const [state, setState] = useState<"idle" | "sending" | "done">("idle");
  const [err, setErr] = useState("");
  const phil = useRef<HTMLElement>(null);
  const [seen, setSeen] = useState(false);
  useEffect(() => {
    const el = phil.current;
    if (!el || typeof IntersectionObserver === "undefined") { setSeen(true); return; }
    const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setSeen(true); io.disconnect(); } }, { threshold: 0.4 });
    io.observe(el);
    return () => io.disconnect();
  }, []);

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    const v = email.trim().toLowerCase();
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v)) { setErr("Fadlan geli email sax ah."); return; }
    setState("sending"); setErr("");
    const { error } = await supabase.from("subscribers").insert({ email: v });
    if (error && error.code !== "23505") { setErr("Waa la waayay in la diiwaangeliyo. Isku day mar kale."); setState("idle"); return; }
    setState("done");
  }

  return (
    <div className="ks">
      <style>{CSS}</style>
      <div className="ks-wrap">
        <header className="ks-head">
          <a className="ks-brand" href="#home"><img src={LOGO} alt="" />MIRO<span>STORE</span></a>
          <nav className="ks-nav" aria-label="Menu">
            <a href="#home">Home</a>
            <a href="#about">About</a>
            <a href="#contact">Contact</a>
          </nav>
        </header>

        <section className="ks-hero" id="home">
          <div>
            <h1>Shaarar linen ah<em>dhawaan buu furmayaa</em></h1>
            <hr className="ks-rule" />
            <p>Shaarar Linen ah oo gacanta lagu tolo ayaa dhawaan kuu iman doona, tayo aad dareemi karto. Is diiwaangeli email-kaaga si aad u noqoto qofka ugu horreeya ee ogaada marka aan furno.</p>
            {state === "done" ? (
              <p className="ks-ok" role="status">Mahadsanid! Waa lagu diiwaangeliyay.</p>
            ) : (
              <form className="ks-form" onSubmit={submit} noValidate>
                <input type="email" autoComplete="email" placeholder="Email-kaaga" aria-label="Email" value={email} onChange={(e) => setEmail(e.target.value)} />
                <button type="submit" disabled={state === "sending"}>{state === "sending" ? "Waa la diraya..." : "Is diiwaangeli"}</button>
              </form>
            )}
            {err && <p className="ks-err" role="alert">{err}</p>}
          </div>
          <div className="ks-img"><img src={FABRIC} alt="Marada Linen" /></div>
        </section>
      </div>

      <section className="ks-phil" id="philosophy" ref={phil}>
        <div className="ks-wrap">
          <div className="ks-label">Our Philosophy</div>
          <blockquote>&ldquo;Labiskaagu uma baahna inuu qaylo sameeyo si laguugu garto.&rdquo;</blockquote>
          <p>Xarragadu buuq uma baahna; tayada ayaa iskeed u hadasha.</p>
          <small className={"ks-name" + (seen ? " ks-in" : "")} aria-label="MIRO STORE.so">
            {Array.from("MIRO STORE.so").map((c, i) => (
              <span key={i} aria-hidden="true" style={{ ["--i" as string]: i } as React.CSSProperties}>{c === " " ? "\u00a0" : c}</span>
            ))}
          </small>
        </div>
      </section>

      <section className="ks-sec" id="about">
        <div className="ks-wrap ks-grid">
          <div className="ks-label">About</div>
          <div><h2>Linen waa maxay?</h2><p>Linen waa maro dabiici ah oo laga sameeyo geedka Flax, waana mid lagu yaqaan quruxdeeda, neefsashada hawada iyo raaxada ay bixiso. Waxaan Miro Store u doorannay Linen sababtoo ah labis wanaagsan ma ahan muuqaalka oo keliya, balse waa tayada marada iyo raaxada qofka xiranaya.</p></div>
        </div>
      </section>

      <section className="ks-sec" id="contact">
        <div className="ks-wrap ks-grid">
          <div className="ks-label">Contact</div>
          <div>
            <a className="ks-tel" href="https://wa.me/252770714732">+252 77 071 4732</a>
            <div className="ks-links">
              {LINKS.map((c) => (
                <a key={c.k} href={c.h} rel="noopener noreferrer" aria-label={c.l}><svg viewBox="0 0 24 24" aria-hidden="true"><path d={ICONS[c.k as keyof typeof ICONS]} /></svg></a>
              ))}
            </div>
          </div>
        </div>
      </section>

      <footer className="ks-wrap ks-foot"><span>&copy; Miro Store</span><span>Quality You Can Feel.</span></footer>
    </div>
  );
}
